em" role="listitem"><span class="tag-small" style="background-color:#e6ff2b;color:black"><span class="tag-small__text">Jaipur</span></span></div><div class="books-slider__genre-list-item w-dyn-item" role="listitem"><span class="tag-small" style="background-color:#3d3195;color:white"><span class="tag-small__text">In-Store</span></span></div></div></div></div></div><a aria-label="Read more" class="books-slider__item-link w-inline-block" href="#"></a></div></article></div></div></div></div></div></div></div></div></div></div></section><section class="flow is--inner-clip is--bg-soft-pink"><div class="flow__container u-container"><div class="flow__inner"><header class="flow__header"><h2 class="flow__title u-heading-l">How it works</h2><div class="flow__text-wrap"><div class="flow__text-outer"><p class="flow__text u-handwritten-regular" data-handwritten-text-inview="">Consider us your personal pet concierge</p></div></div><div class="flow__cta"><img alt="Furry Friends Icon" class="flow__cta-logo" loading="lazy" src="furry-friends-logo.png" style="border-radius: 50%; object-fit: contain;"/><a class="button-alt w-inline-block" data-button-alt="" data-wf--button-alt--variant="base" href="#" target="_blank"><span class="button-alt__text-wrap"><span class="button-alt__bg"></span><span class="button-alt__text-outer"><span class="button-alt__text" data-button-alt-text="">Explore Pet Club</span></span></span><span class="button-alt__icon-wrap"><span class="button-alt__bg"></span><span class="button-alt__icon-outer"><svg aria-hidden="true" class="button-alt__icon" fill="none" viewbox="0 0 14 13" width="100%" xmlns="http://www.w3.org/2000/svg"><path d="M13.58 5.66v.845l-5.994 5.66-1.71-2.063a61.427 61.427 0 0 1 4.265-2.988l-.02-.078c-1.828.196-4.107.294-6.387.294H0V4.835h3.734c2.28 0 4.56.098 6.387.294l.02-.059a67.638 67.638 0 0 1-4.265-3.006L7.586 0l5.994 5.66Z" fill="currentColor"></path></svg></span></span></a></div></header><div class="flow__content"><div class="flow__list" data-call-out=""><div class="flow__list-item" data-call-out-item=""><div class="flow__card" data-call-out-child="" data-wf--flow-card--variant="base"><div class="flow__card-inner"><div class="flow__card-header"><span class="flow__card-header-title u-handwritten-big">Step #1</span></div><div class="flow__card-img-wrap"><img alt="Step 1 Illustration" class="flow__card-img" height="588" loading="lazy" src="https://cdn.prod.website-files.com/696173cb00865d1b386e4af8/69849eba6ebf97ec498a7a57_01_step-illustration.webp" width="720"/></div><div class="flow__card-content"><h3 class="flow__card-content-title u-heading-s">Explore our essentials</h3><p class="flow__card-content-paragraph u-paragraph-regular">The first of every month we reveal fresh new treats, gourmet food, and grooming packages. Follow us on socials for sneak peeks!</p></div></div></div></div><div class="flow__list-item" data-call-out-item=""><div class="flow__card" data-call-out-child="" data-wf--flow-card--variant="bright-pink"><div class="flow__card-inner"><div class="flow__card-header"><span class="flow__card-header-title u-handwritten-big">Step #2</span></div><div class="flow__card-img-wrap"><img alt="Step 2 Illustration" class="flow__card-img" height="588" loading="lazy" src="https://cdn.prod.website-files.com/696173cb00865d1b386e4af8/69849eba1f866c516a514ade_02_step-illustration.webp" width="720"/></div><div class="flow__card-content"><h3 class="flow__card-content-title u-heading-s">Build your pet box</h3><p class="flow__card-content-paragraph u-paragraph-regular">Pet parents can order customized boxes with their fur baby's favorite foods, healthy treats, and durable chew toys.</p></div></div></div></div><div class="flow__list-item" data-call-out-item=""><div class="flow__card" data-call-out-child="" data-wf--flow-card--variant="yellow"><div class="flow__card-inner"><div class="flow__card-header"><span class="flow__card-header-title u-handwritten-big">Step #3</span></div><div class="flow__card-img-wrap"><img alt="Step 3 Illustration" class="flow__card-img" height="588" loading="lazy" src="https://cdn.prod.website-files.com/696173cb00865d1b386e4af8/69849ebaea8f91077664d474_03_step-illustration.webp" width="720"/></div><div class="flow__card-content"><h3 class="flow__card-content-title u-heading-s">Check your doorstep</h3><p class="flow__card-content-paragraph u-paragraph-regular">Your box is delivered right to your doorstep in Jaipur in express time. The best excuse to cancel plans and pamper your pet.</p></div></div></div></div><div class="flow__list-item" data-call-out-item=""><div class="flow__card" data-call-out-child="" data-wf--flow-card--variant="periwinkle"><div class="flow__card-inner"><div class="flow__card-header"><span class="flow__card-header-title u-handwritten-big">Step #4</span></div><div class="flow__card-img-wrap"><img alt="Kommunikation Nachrichten" class="flow__card-img" height="588" loading="lazy" src="https://cdn.prod.website-files.com/696173cb00865d1b386e4af8/6a354b17bd64236c99a93c7e_Step%20Illustration.webp" width="720"/></div><div class="flow__card-content"><h3 class="flow__card-content-title u-heading-s">Share your happy paws</h3><p class="flow__card-content-paragraph u-paragraph-regular">Share your unboxing and tag us @furryfriendsjaipur or visit our stores in Vidhyadhar Nagar &amp; Agra Road, Jaipur!</p></div></div></div></div></div><div class="flow__content-text-wrap"><div class="flow__content-text-outer"><p class="flow__text u-handwritten-regular" data-handwritten-text-inview="">Consider us your professional book curator</p></div></div></div></div></div><div class="flow__bg"><svg class="flow__bg-svg is--desktop" data-background-animation="" fill="none" viewbox="0 0 1920 1078" xmlns="http://www.w3.org/2000/svg"><path d="M1036.04 224.719c46.68-18.686 94.68-27.593 145.01-17.193 69.48 14.366 110.3 57.983 128.04 125.006 15.96 60.318 6.45 120.498-1.31 180.811-8.29 64.443-17.14 128.943-21.73 193.698-3.4 47.933 9.35 93.628 35.22 135.082 24.6 39.4