  const book = document.getElementById("heroBook");
  if (book) {
    window.addEventListener("mousemove", function(e) {
      const rect = book.getBoundingClientRect();
      const x = (e.clientX - (rect.left + rect.width / 2)) / (window.innerWidth / 2);
      const y = (e.clientY - (rect.top + rect.height / 2)) / (window.innerHeight / 2);
      book.style.transform = `rotateY(${-24 + x * 14}deg) rotateX(${10 - y * 12}deg) rotateZ(${-4 + x * 2}deg)`;
    });
    book.addEventListener("mouseleave", function() {
      book.style.transform = "rotateY(-24deg) rotateX(10deg) rotateZ(-4deg)";
    });
  }
});
