document.addEventListener("DOMContentLoaded", function() {
  const boxWrap = document.querySelector('.box__wrap') || document.querySelector('.box');
  const plateBrand = document.querySelector('.box-green-plate-brand');
  
  if (boxWrap && plateBrand) {
    function checkPlateVisibility() {
      const rect = boxWrap.getBoundingClientRect();
      const windowH = window.innerHeight;
      // When the box section is in view
      const topVisible = rect.top < windowH * 0.65;
      const bottomVisible = rect.bottom > windowH * 0.35;
      
      if (topVisible && bottomVisible) {
        plateBrand.classList.add('is--visible');
      } else {
        plateBrand.classList.remove('is--visible');
      }
    }
    
    window.addEventListener('scroll', checkPlateVisibility, { passive: true });
    window.addEventListener('resize', checkPlateVisibility);
    checkPlateVisibility();
  }
});
</script>
<script>
document.addEventListener('DOMContentLoaded', () => {
  const boxSection = document.querySelector('.box');
  const floatingBar = document.getElementById('floatingContactBar');
  if (boxSection && floatingBar) {
    const obs = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          floatingBar.style.transition = 'opacity 0.35s ease, transform 0.35s ease';
          floatingBar.style.opacity = '0';
          floatingBar.style.pointerEvents = 'none';
          floatingBar.style.transform = 'translateY(30px)';
        } else {
          floatingBar.style.transition = 'opacity 0.35s ease, transform 0.35s ease';
          floatingBar.style.opacity = '1';
          floatingBar.style.pointerEvents = 'auto';
          floatingBar.style.transform = 'translateY(0)';
        }
      });
    }, { threshold: 0.1 });
    obs.observe(boxSection);
  }
});
</script>

